# Analyze shapes
from collections import deque

def find_components(grid):
    rows, cols = len(grid), len(grid[0])
    visited = set()
    components = []
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 2 and (r,c) not in visited:
                comp = []
                dq = deque([(r,c)])
                visited.add((r,c))
                while dq:
                    cr, cc = dq.popleft()
                    comp.append((cr, cc))
                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                        nr, nc = cr+dr, cc+dc
                        if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == 2 and (nr,nc) not in visited:
                            visited.add((nr,nc))
                            dq.append((nr,nc))
                components.append(comp)
    return components

def get_bbox_min(comp):
    rs = [r for (r,c) in comp]
    cs = [c for (r,c) in comp]
    return min(rs), min(cs)

def get_bbox_max(comp):
    rs = [r for (r,c) in comp]
    cs = [c for (r,c) in comp]
    return max(rs), max(cs)

def bbox_coverage(comp):
    """Returns 1 if component fills its bounding box (solid), 0 if not"""
    rs = [r for (r,c) in comp]
    cs = [c for (r,c) in comp]
    min_r, min_c = min(rs), min(cs)
    max_r, max_c = max(rs), max(cs)
    expected = (max_r - min_r + 1) * (max_c - min_c + 1)
    return len(comp) == expected

def shape_signature(comp):
    """Simple shape signature: normalized set of relative coordinates"""
    min_r, min_c = get_bbox_min(comp)
    return tuple(sorted([(r-min_r, c-min_c) for (r,c) in comp]))

components = find_components(input1)

print("Component details:")
patterns = {}
signatures = {}
for i, comp in enumerate(components):
    sig = shape_signature(comp)
    bb_min = get_bbox_min(comp)
    bb_coverage = bbox_coverage(comp)
    sig_name = len(sig)
    print(f"Comp {i}: sig={sig}, bbox_min={bb_min}, coverage={bb_coverage}")
    if sig not in patterns:
        patterns[sig] = []
    patterns[sig].append((i, bb_min))
    signatures[sig] = True

print("\nPattern counts:", {k: len(v) for k, v in patterns.items()})

